INSERT OR REPLACE INTO "FC Horizon IN" SELECT coalesce(k0."Versions", error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k1."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
